            var earlyCore = new GreedLastRunCore();
            GreedLastRunSnapshot earlySnapshot = default;
            earlyCore.SnapshotChanged += value => earlySnapshot = value;
            earlyCore.Enter("live coach early smoke", refillRun: false);
