        private static void VerifyRuntimeBoardScreenRenderVisibility()
        {
            GameObject existingCamera = GameObject.Find("GreedLastCamera");
            GameObject existingEventSystem = GameObject.Find("GreedLastEventSystem");
            GameObject host = new GameObject("GreedLastRuntimeUiBoardSmokeHost");
            GameObject canvasRoot = null;

            try
            {
                GreedLastRuntimeUi ui = host.AddComponent<GreedLastRuntimeUi>();
                InitializeRuntimeUiSmoke(ui);

                GameObject lanePreviewRoot = GetRuntimeUiField<GameObject>(ui, "lanePreviewRoot");
                Text subtitleText = GetRuntimeUiField<Text>(ui, "subtitleText");
                Text detailText = GetRuntimeUiField<Text>(ui, "detailText");
                Text runHudText = GetRuntimeUiField<Text>(ui, "runHudText");
                Text[] laneLabelTexts = GetRuntimeUiField<Text[]>(ui, "laneLabelTexts");
                Button[] laneButtons = GetRuntimeUiField<Button[]>(ui, "laneButtons");
                Button normalRunButton = GetRuntimeUiField<Button>(ui, "normalRunButton");
                Button saveLoadoutButton = GetRuntimeUiField<Button>(ui, "saveLoadoutButton");
                Button infiniteButton = GetRuntimeUiField<Button>(ui, "infiniteButton");
                Button nextPatternButton = GetRuntimeUiField<Button>(ui, "nextPatternButton");
                Button saveSlotDetailButton = GetRuntimeUiField<Button>(ui, "saveSlotDetailButton");
                Button returnLobbyButton = GetRuntimeUiField<Button>(ui, "returnLobbyButton");
                Button rotationTiltButton = GetRuntimeUiField<Button>(ui, "rotationTiltButton");
                Image[] lobbyRunPortalPieces = GetRuntimeUiField<Image[]>(ui, "lobbyRunPortalPieces");
                Image[] lobbyRunPortalPips = GetRuntimeUiField<Image[]>(ui, "lobbyRunPortalPips");
                Image rotationInputCursor = GetRuntimeUiField<Image>(ui, "straightRunRotationInputCursor");
                Image rotationNeutralGate = GetRuntimeUiField<Image>(ui, "straightRunRotationNeutralGate");
                Image[] rotationTiltPips = GetRuntimeUiField<Image[]>(ui, "straightRunRotationTiltPips");
                Image[] rotationGripBars = GetRuntimeUiField<Image[]>(ui, "straightRunRotationGripBars");
                GameObject runnerAvatarRoot = GetRuntimeUiField<GameObject>(ui, "runnerAvatarRoot");
                CanvasGroup runnerAvatarCanvasGroup = GetRuntimeUiField<CanvasGroup>(ui, "runnerAvatarCanvasGroup");
                Image runnerShadow = GetRuntimeUiField<Image>(ui, "runnerShadow");
                GameObject rootPanel = GetRuntimeUiField<GameObject>(ui, "rootPanel");
                if (rootPanel != null)
                {
                    canvasRoot = rootPanel.transform.root.gameObject;
                }

                Require(
                    rotationInputCursor != null && rotationTiltButton != null,
                    "Runtime UI must create the mobile rotation sensor cursor and persisted tilt preference button.");
                InvokeRuntimeUiInstance(
                    ui,
                    "UpdateStraightRunRotationInputCursor",
                    true,
                    -1f,
                    0.8f,
                    -0.7f,
                    -1,
                    0.5f,
                    new Color32(224, 177, 74, 255));
                Color32 correctTiltCursorColor = rotationInputCursor.color;
                Require(
                    rotationInputCursor.rectTransform.anchorMin.x < 0.5f
                        && correctTiltCursorColor.a > 0,
                    "Runtime mobile tilt cursor must move left and become visible for a deliberate left sensor read.");
                InvokeRuntimeUiInstance(
                    ui,
                    "UpdateStraightRunRotationInputCursor",
                    true,
                    -1f,
                    0.8f,
                    0.7f,
                    1,
                    0.5f,
                    new Color32(224, 177, 74, 255));
                Color32 wrongTiltCursorColor = rotationInputCursor.color;
                Require(
                    rotationInputCursor.rectTransform.anchorMin.x > 0.5f
                        && wrongTiltCursorColor.a > 0
                        && wrongTiltCursorColor.g < correctTiltCursorColor.g,
                    "Runtime mobile tilt cursor must move right and switch to the wrong-direction warning color.");
                SetRuntimeUiField(ui, "rotationTiltInputAvailable", false);
                InvokeRuntimeUiInstance(
                    ui,
                    "UpdateStraightRunRotationTiltPips",
                    true,
                    -1f,
                    0.85f,
                    1f,
                    0f,
                    0f,
                    GreedLastJudgementResult.None);
                Require(
                    rotationNeutralGate != null
                        && rotationNeutralGate.color.a == 0
                        && rotationInputCursor.color.a == 0
                        && rotationGripBars != null
                        && rotationGripBars.Length == 2
                        && rotationGripBars[0].color.a == 0
                        && rotationGripBars[1].color.a == 0
                        && rotationTiltPips != null
                        && rotationTiltPips.Length == 5
                        && (rotationTiltPips[0].color.a > 0
                            || rotationTiltPips[1].color.a > 0
                            || rotationTiltPips[2].color.a > 0
                            || rotationTiltPips[3].color.a > 0
                            || rotationTiltPips[4].color.a > 0),
                    "Runtime tap fallback must hide tilt-only controls while preserving the rotation-direction pips.");
                SetRuntimeUiField(ui, "rotationTiltInputAvailable", true);

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.LobbyReady, "Lobby", "action notice", 0));
                InvokeRuntimeUiInstance(ui, "UpdateLobbyRunPortal", 1f);
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                Require(lanePreviewRoot != null && lanePreviewRoot.activeSelf, "Lobby rendering must keep the lane preview visible.");
                Require(
                    !laneButtons[0].gameObject.activeSelf && !laneButtons[1].gameObject.activeSelf
                        && !laneButtons[2].gameObject.activeSelf
                        && !GetRuntimeUiField<Image>(ui, "judgementLine").enabled
                        && !GetRuntimeUiField<Image>(ui, "beatMarker").enabled
                        && GetRuntimeUiField<RawImage>(ui, "prototypeEntranceBackdrop").texture
                            == Resources.Load<Texture2D>("GreedLast/PrototypeLobby"),
                    "The illustrated lobby must show the character-free plate and one runtime runner without lane labels, a judgement line, or the old square marker.");
                Require(subtitleText != null && !string.IsNullOrEmpty(subtitleText.text), "Lobby rendering must keep the mode subtitle visible.");
                Require(
                    lobbyRunPortalPieces != null
                        && lobbyRunPortalPieces.Length == 4
                        && lobbyRunPortalPieces[3] != null
                        && lobbyRunPortalPieces[3].color.a > 0
                        && lobbyRunPortalPips != null
                        && lobbyRunPortalPips.Length == 3
                        && lobbyRunPortalPips[0] != null
                        && lobbyRunPortalPips[0].color.a > 0,
                    "A ready lobby render must create and light the entrance portal threshold and forward pips.");
                Require(
                    runnerAvatarRoot != null
                        && runnerAvatarRoot.activeSelf
                        && runnerAvatarCanvasGroup != null
                        && runnerAvatarCanvasGroup.alpha > 0.8f
                        && runnerAvatarCanvasGroup.alpha < 1f
                        && runnerAvatarRoot.transform.localScale.x < 0.7f
                        && runnerShadow != null
                        && runnerShadow.gameObject.activeSelf
                        && normalRunButton.transform.localScale.x > 1f,
                    "A ready lobby render must stage the existing runner as a small breathing silhouette at the portal threshold.");
                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.LobbyReady,
                    "Lobby",
                    "저장 조합이 비었습니다.\n다음 확인: 보충 후 무한 재진입 / 실행: 무한 조합 보충",
                    0,
                    hasUsableSaveSlots: false,
                    hasOccupiedSaveSlots: false));
                Require(
                    normalRunButton != null
                        && normalRunButton.gameObject.activeSelf
                        && saveLoadoutButton != null
                        && saveLoadoutButton.gameObject.activeSelf
                        && infiniteButton != null
                        && infiniteButton.gameObject.activeSelf,
                    "An auto-cleared lobby render must keep the refill-related lobby actions visible.");
                Require(
                    GetButtonLabel(normalRunButton) == "보충 런"
                        && GetButtonLabel(saveLoadoutButton) == "보충 안내"
                        && GetButtonLabel(infiniteButton) == "무한 조합 보충",
                    "An auto-cleared lobby render must route normal/save/infinite buttons to refill. Actual: "
                        + GetButtonLabel(normalRunButton)
                        + " / "
                        + GetButtonLabel(saveLoadoutButton)
                        + " / "
                        + GetButtonLabel(infiniteButton));
                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.LobbyReady,
                    "Lobby",
                    "저장 후보 우선\n다음 확인: 보충 후 무한 재진입",
                    0,
                    hasUsableSaveSlots: false,
                    hasOccupiedSaveSlots: false,
                    saveCandidateAvailable: true));
                InvokeRuntimeUiInstance(ui, "UpdateLobbyRunPortal", 1f);
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                Require(
                    GetButtonLabel(normalRunButton) == "후보 먼저 저장"
                        && GetButtonLabel(saveLoadoutButton) == "저장 슬롯 선택 추천 S1"
                        && GetButtonLabel(infiniteButton) == "무한 후보 저장 필요",
                    "A lobby render with a pending candidate must prioritize save/skip before refill routing. Actual: "
                        + GetButtonLabel(normalRunButton)
                        + " / "
                        + GetButtonLabel(saveLoadoutButton)
                        + " / "
                        + GetButtonLabel(infiniteButton));
                Require(
                    lobbyRunPortalPips[0].color.a == 0
                        && lobbyRunPortalPips[1].color.a == 0
                        && lobbyRunPortalPips[2].color.a == 0,
                    "A pending save candidate must dim the lobby run portal and suppress its forward pips.");
                Require(
                    !runnerAvatarRoot.activeSelf && !runnerShadow.gameObject.activeSelf,
                    "A pending save candidate must hide the lobby runner so the save decision remains the only staged action.");
                Require(
                    Mathf.Approximately(normalRunButton.transform.localScale.x, 1f),
                    "A pending save candidate must reset normal-run button breathing so it cannot compete with the save decision.");

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.ReSyncPending, "Sync", "동기화 중", 0));
                InvokeRuntimeUiInstance(ui, "UpdateLobbyRunPortal", 1f);
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                Require(
                    lobbyRunPortalPieces[0].color.a == 0
                        && lobbyRunPortalPieces[1].color.a == 0
                        && lobbyRunPortalPieces[2].color.a == 0
                        && lobbyRunPortalPieces[3].color.a == 0,
                    "Re-sync rendering must hide the lobby run portal instead of advertising a blocked start.");
                Require(
                    !runnerAvatarRoot.activeSelf && !runnerShadow.gameObject.activeSelf,
                    "Re-sync rendering must hide the lobby runner together with the blocked entrance portal.");
                Require(
                    Mathf.Approximately(normalRunButton.transform.localScale.x, 1f),
                    "Re-sync rendering must reset normal-run button breathing together with the blocked portal.");
                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.LobbyReady,
                    "Lobby",
                    "보충 안내 / 저장 후보 없음 / 저장 조합 없음\n보충 런 버튼: 보충 런 진입",
                    0,
                    hasUsableSaveSlots: true,
                    hasOccupiedSaveSlots: true,
                    saveCandidateAvailable: true));
                Require(
                    GetButtonLabel(normalRunButton) == "후보 먼저 저장"
                        && GetButtonLabel(saveLoadoutButton) == "저장 슬롯 선택 S1"
                        && GetButtonLabel(infiniteButton) == "무한 후보 저장 필요",
                    "A lobby render with a pending candidate must keep save-first buttons even with condensed refill-button copy. Actual: "
                        + GetButtonLabel(normalRunButton)
                        + " / "
                        + GetButtonLabel(saveLoadoutButton)
                        + " / "
                        + GetButtonLabel(infiniteButton));

                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.SaveLoadoutDraft,
                    "Save Draft",
                    "보충 안내 / 저장 후보 없음 / 저장 조합 없음\n다음: 보충 런 클리어 후 새 조합 저장",
                    0,
                    hasUsableSaveSlots: false,
                    hasOccupiedSaveSlots: false));
                Require(
                    nextPatternButton != null
                        && saveSlotDetailButton != null
                        && returnLobbyButton != null
                        && nextPatternButton.gameObject.activeSelf
                        && saveSlotDetailButton.gameObject.activeSelf
                        && returnLobbyButton.gameObject.activeSelf,
                    "An all-empty save-loadout draft render must expose refill, guidance, and lobby return actions.");
                Require(
                    GetButtonLabel(nextPatternButton) == "보충 런"
                        && GetButtonLabel(saveSlotDetailButton) == "보충 안내"
                        && GetButtonLabel(returnLobbyButton) == "로비로",
                    "An all-empty save-loadout draft render must route buttons to refill guidance. Actual: "
                        + GetButtonLabel(nextPatternButton)
                        + " / "
                        + GetButtonLabel(saveSlotDetailButton)
                        + " / "
                        + GetButtonLabel(returnLobbyButton));

                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.InfiniteStartReady,
                    "Infinite Prep",
                    "저장 조합 없음\n보충 런 버튼: 보충 런 진입\n다음: 보충 런 클리어 후 새 조합 저장",
                    0,
                    hasUsableSaveSlots: false,
                    hasOccupiedSaveSlots: false));
                Require(
                    saveLoadoutButton != null
                        && nextPatternButton != null
                        && returnLobbyButton != null
                        && saveLoadoutButton.gameObject.activeSelf
                        && nextPatternButton.gameObject.activeSelf
                        && returnLobbyButton.gameObject.activeSelf
                        && !normalRunButton.gameObject.activeSelf
                        && !infiniteButton.gameObject.activeSelf,
                    "An all-empty infinite-prep render must expose only refill-ready preparation actions.");
                Require(
                    GetButtonLabel(saveLoadoutButton) == "보충 안내"
                        && GetButtonLabel(nextPatternButton) == "보충 런"
                        && GetButtonLabel(returnLobbyButton) == "로비로",
                    "An all-empty infinite-prep render must route the management and start buttons to refill. Actual: "
                        + GetButtonLabel(saveLoadoutButton)
                        + " / "
                        + GetButtonLabel(nextPatternButton)
                        + " / "
                        + GetButtonLabel(returnLobbyButton));

                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.InfiniteStartReady,
                    "Infinite Prep",
                    "재시작: S2 안정형\n저장 조합 변경으로 다른 슬롯을 고를 수 있습니다.",
                    0,
                    hasUsableSaveSlots: true,
                    hasOccupiedSaveSlots: true));
                Require(
                    GetButtonLabel(saveLoadoutButton) == "저장 조합 변경"
                        && GetButtonLabel(nextPatternButton) == "시작 -1회"
                        && GetButtonLabel(returnLobbyButton) == "로비로",
                    "An infinite-prep render with a usable save loadout must stay on stored-loadout start instead of refill. Actual: "
                        + GetButtonLabel(saveLoadoutButton)
                        + " / "
                        + GetButtonLabel(nextPatternButton)
                        + " / "
                        + GetButtonLabel(returnLobbyButton));

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteRecordBoard, "Records", "[S] 1000 / 44m / combo 5", 2));
                Require(lanePreviewRoot != null && !lanePreviewRoot.activeSelf, "Record-board rendering must hide the lane preview root.");
                Require(subtitleText != null && string.IsNullOrEmpty(subtitleText.text), "Record-board rendering must hide the generic mode subtitle.");
                Require(runHudText != null && !runHudText.gameObject.activeSelf, "Record-board rendering must not leave the run HUD visible.");
                Require(detailText != null && detailText.text.Contains("[S] 1000", StringComparison.Ordinal), "Record-board rendering must keep the record detail text.");
                Require(
                    !normalRunButton.gameObject.activeSelf
                        && !saveLoadoutButton.gameObject.activeSelf
                        && !infiniteButton.gameObject.activeSelf,
                    "Record-board rendering must hide lobby action buttons so the board reads as records first.");
                string recordNavigationLabels = GetButtonLabel(nextPatternButton)
                    + " / "
                    + GetButtonLabel(saveSlotDetailButton)
                    + " / "
                    + GetButtonLabel(returnLobbyButton);
                Require(
                    nextPatternButton != null
                        && nextPatternButton.gameObject.activeSelf
                        && saveSlotDetailButton != null
                        && saveSlotDetailButton.gameObject.activeSelf
                        && returnLobbyButton != null
                        && returnLobbyButton.gameObject.activeSelf,
                    "Record-board rendering must keep only the compact navigation buttons visible.");
                Require(
                    recordNavigationLabels == "다음 / 이전 / 로비로",
                    "Record-board navigation buttons must stay short and must not repeat page names. Actual: "
                        + recordNavigationLabels);
                Require(
                    !recordNavigationLabels.Contains("일반", StringComparison.Ordinal)
                        && !recordNavigationLabels.Contains("무한", StringComparison.Ordinal)
                        && !recordNavigationLabels.Contains("랭킹", StringComparison.Ordinal),
                    "Record-board navigation controls must not bring page labels back into the playfield.");
                Require(
                    laneLabelTexts != null
                        && laneLabelTexts.Length >= 3
                        && laneLabelTexts[0].text == "좌"
                        && laneLabelTexts[1].text == "중"
                        && laneLabelTexts[2].text == "우",
                    "Record-board lane labels must stay as direction names only, with page names reserved for the title/buttons.");
                Require(
                    laneButtons != null
                        && laneButtons.Length >= 3
                        && !laneButtons[0].interactable
                        && !laneButtons[1].interactable
                        && !laneButtons[2].interactable,
                    "Record-board lane columns must not act like page selectors after navigation moved to bottom buttons.");

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.ProfileBoard, "Profile", "prototype progress", 0));
                Require(lanePreviewRoot != null && !lanePreviewRoot.activeSelf, "Profile-board rendering must hide the lane preview root.");
                Require(subtitleText != null && string.IsNullOrEmpty(subtitleText.text), "Profile-board rendering must hide the generic mode subtitle.");
                Require(runHudText != null && !runHudText.gameObject.activeSelf, "Profile-board rendering must not leave the run HUD visible.");
                Require(
                    !normalRunButton.gameObject.activeSelf
                        && !saveLoadoutButton.gameObject.activeSelf
                        && !infiniteButton.gameObject.activeSelf,
                    "Profile-board rendering must hide lobby action buttons so profile traces do not compete with lobby actions.");
                ui.Render(BuildUiScreenSnapshot(
                    GreedLastScreenState.ProfileBoard,
                    "Profile",
                    "저장 후보\n성장 보정\n대표 기록",
                    1));
                Require(
                    detailText != null
                        && detailText.text.Contains("저장 후보", StringComparison.Ordinal)
                        && detailText.text.Contains("성장 보정", StringComparison.Ordinal),
                    "Profile-board page-one rendering must keep the storage/growth detail visible after NEW shortcuts route here.");
                string profileNavigationLabels = GetButtonLabel(saveSlotDetailButton)
                    + " / "
                    + GetButtonLabel(nextPatternButton)
                    + " / "
                    + GetButtonLabel(returnLobbyButton);
                Require(
                    profileNavigationLabels == "이전: 1/4 요약 / 다음: 3/4 장식 / 로비로",
                    "Profile-board page-one navigation must stay clear when profile NEW shortcuts open storage/growth details. Actual: "
                        + profileNavigationLabels);
                Require(
                    laneLabelTexts != null
                        && laneLabelTexts.Length >= 3
                        && laneLabelTexts[0].text.Contains("요약", StringComparison.Ordinal)
                        && laneLabelTexts[1].text.Contains("기록", StringComparison.Ordinal)
                        && laneLabelTexts[2].text.Contains("장식", StringComparison.Ordinal),
                    "Profile-board page-one lane labels must point left to summary, center to record board, and right to badge details.");
                VerifyReadableMenuAndResultLayouts(ui);
            }
            finally
            {
                if (canvasRoot != null)
                {
                    UnityEngine.Object.DestroyImmediate(canvasRoot);
                }

                DestroySmokeCreatedObject("GreedLastCamera", existingCamera);
                DestroySmokeCreatedObject("GreedLastEventSystem", existingEventSystem);
                GreedLastPrototypeAudioCheck.ReleaseEditorAudio(host);
                UnityEngine.Object.DestroyImmediate(host);
            }
        }

        private static void VerifyReadableMenuAndResultLayouts(GreedLastRuntimeUi ui)
        {
            VerifyPlayfieldReadability(ui);
            VerifyCompactTimingGuide(ui);
            VerifyCompactActionCues(ui);
            GreedLastPrototypeHudCheck.Run();
            GreedLastPrototypeHudCheck.VerifyIdleSafeAreaRefresh(ui);
            GreedLastPrototypeHudCheck.VerifyRunTransitions(ui);
            GreedLastPrototypeHudCheck.VerifyCompactProgress(ui);
            GreedLastPrototypeAudioCheck.Run(ui);
            GreedLastPrototypePointerCheck.Run(ui);
            string longDetail = string.Join("\n", new string[40]).Replace("\n", "비교 기록 12345 / 마지막 1회\n") + "마지막 비교 항목";
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.SaveLoadoutDraft, "저장 슬롯 선택", longDetail, 0,
                saveCandidateAvailable: true, selectedSaveSlotIndex: 2));
            ScrollRect scroll = GetRuntimeUiField<ScrollRect>(ui, "menuDetailScroll");
            Text detail = GetRuntimeUiField<Text>(ui, "detailText");
            RectTransform root = GetRuntimeUiField<RectTransform>(ui, "rootPanelRect");
            Button[] lanes = GetRuntimeUiField<Button[]>(ui, "laneButtons");
            Require(scroll.gameObject.activeSelf && scroll.content == detail.rectTransform && detail.fontSize >= 38,
                "Management detail must stay readable in a dedicated scroll viewport.");
            Require(scroll.content.rect.height > scroll.viewport.rect.height && scroll.verticalNormalizedPosition > 0.99f,
                "Long comparison text must scroll from its beginning instead of shrinking or overflowing onto slots.");
            Require(scroll.verticalScrollbar.gameObject.activeSelf, "Overflowing comparison text must expose its scrollbar.");
            Rect viewportBounds = BoundsInRoot(scroll.GetComponent<RectTransform>(), root);
            var slotBounds = new List<Rect>();
            foreach (Button lane in lanes)
            {
                Rect bounds = BoundsInRoot(lane.GetComponent<RectTransform>(), root);
                Require(!bounds.Overlaps(viewportBounds), "Slot choices must not overlap the comparison viewport.");
                foreach (Rect previous in slotBounds)
                    Require(!bounds.Overlaps(previous), "Slot choices must not overlap each other.");
                slotBounds.Add(bounds);
            }
            scroll.OnScroll(new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current)
            {
                scrollDelta = new Vector2(0f, -6f),
            });
            Require(scroll.verticalNormalizedPosition < 0.99f, "Wheel input must move long management detail.");
            scroll.verticalNormalizedPosition = 0f;
            Require(scroll.content.anchoredPosition.y > 0f && detail.text.EndsWith("마지막 비교 항목", StringComparison.Ordinal),
                "The bottom of long comparison text must remain reachable without discarding data.");
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteRecordBoard, "기록", "[S] 1000", 2));
            Require(Mathf.Abs(scroll.content.anchoredPosition.y) < 1f && detail.text == "[S] 1000",
                "Changing screens must reset scroll position and retain only that screen's content.");
            Require(!scroll.vertical && !scroll.verticalScrollbar.gameObject.activeSelf,
                "Short records must disable dragging and hide a nonfunctional scrollbar.");
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteStartReady, "무한모드 준비",
                GreedLastApp.BuildInfinitePreparationDetailForStep(0, string.Empty, string.Empty), 0));
            Require(GetRuntimeUiField<GameObject>(ui, "lanePreviewRoot").activeSelf
                && lanes[0].IsInteractable() && lanes[1].IsInteractable() && lanes[2].IsInteractable(),
                "Readable infinite preparation must retain all three actionable gift choices.");
            Require(GetRuntimeUiField<Text[]>(ui, "laneLabelTexts")[0].text.Contains("생존", StringComparison.Ordinal),
                "Infinite preparation must show its current choice labels, not generic directions.");

            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            core.EnterInfiniteRun(new GreedLastRunRecord(true, 500, 3, 0, 0, 2, 3, 0, 0, 20f,
                "테스트 조합", "박자 감각", "집중 축", string.Empty, "집중 축", string.Empty));
            core.ForceStopInfiniteRunForTest();
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteRun, "무한모드", string.Empty, 0));
            ui.RenderRun(run);
            Require(!scroll.gameObject.activeSelf && detail.transform.parent == root && detail.fontSize == 44,
                "A result must leave the management scroll and use its own readable summary.");
            Require(!GetRuntimeUiField<GameObject>(ui, "runGaugeRoot").activeSelf
                && !GetRuntimeUiField<GameObject>(ui, "runProgressRoot").activeSelf
                && !GetRuntimeUiField<Text>(ui, "runHudText").gameObject.activeSelf
                && !GetRuntimeUiField<GameObject>(ui, "lanePreviewRoot").activeSelf,
                "Stopped results must not retain overlapping gameplay gauges, lanes, or debug-sized HUD text.");
            Require(detail.text.Contains("정확", StringComparison.Ordinal) && detail.text.Contains("최대 콤보", StringComparison.Ordinal),
                "Stopped results must preserve judgement and combo totals.");
            core.RestartPractice(Time.realtimeSinceStartup);
            ui.RenderRun(run);
            Require(GetRuntimeUiField<GameObject>(ui, "runGaugeRoot").activeSelf
                && GetRuntimeUiField<GameObject>(ui, "lanePreviewRoot").activeSelf
                && !detail.enabled && lanes[0].GetComponent<RectTransform>().sizeDelta.x == 195f,
                "Restarting play must restore gameplay layout after visiting management and results.");

            float clock = Time.realtimeSinceStartup;
            core.Tick(clock += 2f);
            core.Tick(clock += 1f);
            Require(run.ActivePattern, "The presentation reset check needs a live fresh run.");
            SetRuntimeUiField(ui, "lastComboForBadge", 6);
            SetRuntimeUiField(ui, "comboBreakBadgeUntil", Time.unscaledTime + 5f);
            SetRuntimeUiField(ui, "beatMarkerMissImpactUntil", Time.unscaledTime + 5f);
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.LobbyReady, "입구", string.Empty, 0));
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.RunCoreTest, "연습", string.Empty, 0));
            ui.RenderRun(run);
            Require(GetRuntimeUiValueField<float>(ui, "comboBreakBadgeUntil") == 0f
                && GetRuntimeUiValueField<float>(ui, "beatMarkerMissImpactUntil") == 0f
                && !GetRuntimeUiField<GameObject>(ui, "comboBadgeRoot").activeSelf,
                "A fresh run must clear old combo-loss and damage feedback, even if its first rendered snapshot is already active.");
            GreedLastRunSnapshot beforePause = run;
            core.TogglePause(clock + 0.1f);
            Require(!InvokeRuntimeUiStaticBool("IsNewRunPresentation", beforePause, run),
                "Pausing a run must not be mistaken for a new attempt.");
            GreedLastRunSnapshot paused = run;
            ui.RenderRun(beforePause);
            SetRuntimeUiField(ui, "devCleanViewEnabled", false);
            ui.ToggleDevCleanView();
            Text hud = GetRuntimeUiField<Text>(ui, "runHudText");
            string compactHud = hud.text;
            Require(hud.fontSize == 38 && compactHud.Split('\n').Length == 2
                && compactHud.Contains("콤보", StringComparison.Ordinal) && compactHud.Contains("Miss", StringComparison.Ordinal),
                "Clean view must present readable score and judgement totals without the diagnostic paragraph.");
            const string hiddenHudSentinel = "Hidden diagnostics are built only when requested.";
            SetRuntimeUiField(ui, "detailedRunHud", hiddenHudSentinel);
            VerifyUnchangedRunHud(ui, beforePause, hud);
            Require(GetRuntimeUiField<string>(ui, "detailedRunHud") == hiddenHudSentinel,
                "Clean play must not rebuild a hidden diagnostic paragraph for every run snapshot.");
            ui.RenderRun(paused);
            Text pauseBody = GetRuntimeUiField<Text>(ui, "pauseMenuBodyText");
            Require(pauseBody.fontSize == 36 && pauseBody.text.Split('\n').Length == 3
                && pauseBody.text.Contains("보정 ", StringComparison.Ordinal),
                "Clean pause must show concise live totals and the current timing offset instead of diagnostics.");
            VerifyUnchangedRunHud(ui, paused, hud);
            Require(GetRuntimeUiField<Button>(ui, "motionComfortButton").GetComponentInChildren<Text>().fontSize == 36
                && GetRuntimeUiField<Button[]>(ui, "timingOffsetButtons")[1].GetComponentInChildren<Text>().fontSize == 36,
                "Pause setting buttons must use the readable menu font, including the shared calibration action.");
            ui.RenderRun(beforePause);
            Rect hudBounds = BoundsInRoot(hud.rectTransform, root);
            Require(!hudBounds.Overlaps(BoundsInRoot(GetRuntimeUiField<GameObject>(ui, "runGaugeRoot").GetComponent<RectTransform>(), root))
                && !hudBounds.Overlaps(BoundsInRoot(GetRuntimeUiField<Button>(ui, "nextPatternButton").GetComponent<RectTransform>(), root)),
                "Compact live totals must sit between the gauges and action buttons without overlap.");
            ui.ToggleDevCleanView();
            Require(hud.text != compactHud && hud.text == GetRuntimeUiField<string>(ui, "detailedRunHud"),
                "Toggling clean view off must immediately restore developer detail without restarting play.");
            Require(hud.text != hiddenHudSentinel && hud.text.Contains("점수 " + beforePause.Score, StringComparison.Ordinal),
                "Opening developer detail must rebuild it from the latest snapshot, not a stale hidden cache.");
            VerifyUnchangedRunHud(ui, beforePause, hud);
            VerifyHudModeTransitions(ui, beforePause, hud);

            GreedLastRunSnapshot practiceResult = RunPracticeReviewSample(Time.realtimeSinceStartup,
                new[] { GreedLastJudgementResult.Good, GreedLastJudgementResult.Good, GreedLastJudgementResult.Good });
            ui.ToggleDevCleanView();
            ui.RenderRun(practiceResult);
            Button recommendation = GetRuntimeUiField<Button[]>(ui, "timingOffsetButtons")[1];
            CanvasGroup recommendationGroup = recommendation.GetComponent<CanvasGroup>();
            Require(practiceResult.HasTimingRecommendation && recommendation.gameObject.activeInHierarchy
                && recommendation.IsInteractable() && recommendationGroup.alpha == 1f && recommendationGroup.blocksRaycasts,
                "Practice results must expose the actionable timing recommendation even in clean view.");
            Require(!GetRuntimeUiField<Button>(ui, "pauseButton").gameObject.activeSelf,
                "A terminal result must not display an unusable pause button.");
            Require(!BoundsInRoot(recommendation.GetComponent<RectTransform>(), root).Overlaps(BoundsInRoot(detail.rectTransform, root)),
                "The practice calibration action must sit below the result summary, not over it.");
            int calibrationClicks = 0;
            SetRuntimeUiField<Action<int>>(ui, "timingOffsetRequested", amount => calibrationClicks++);
            try
            {
                var press = new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current)
                    { button = UnityEngine.EventSystems.PointerEventData.InputButton.Left, eligibleForClick = true };
                recommendation.OnPointerDown(press);
                for (int frame = 0; frame < 3; frame++) ui.RenderRun(practiceResult);
                recommendation.OnPointerUp(press);
                if (press.eligibleForClick) recommendation.OnPointerClick(press);
                Require(calibrationClicks == 1, "The result calibration action must survive repeated run redraws while held.");
            }
            finally
            {
                SetRuntimeUiField<Action<int>>(ui, "timingOffsetRequested", null);
            }
            ui.RenderRun(beforePause);
            Require(recommendationGroup.alpha == 0f && !recommendationGroup.blocksRaycasts
                && recommendation.GetComponent<RectTransform>().anchorMin.x > 0.9f,
                "Restarting from practice results must return calibration to the hidden live settings position.");
            ui.ToggleDevCleanView();

            Button action = GetRuntimeUiField<Button>(ui, "nextPatternButton");
            action.interactable = false;
            MethodInfo tone = typeof(GreedLastRuntimeUi).GetMethod("SetButtonTone", BindingFlags.Static | BindingFlags.NonPublic);
            tone.Invoke(null, new object[] { action, new Color32(205, 166, 70, 255), new Color32(238, 204, 114, 255), new Color32(165, 124, 48, 255) });
            Require(action.targetGraphic.color == Color.white && action.GetComponentInChildren<Text>().color.grayscale > 0.7f,
                "A disabled action must retain a readable label and must not be tinted twice.");
        }

        private static void VerifyHudModeTransitions(GreedLastRuntimeUi ui, GreedLastRunSnapshot original, Text hud)
        {
            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            float clock = Time.realtimeSinceStartup;
            core.RestartPractice(clock);
            core.Tick(clock += 2f);
            core.Tick(clock += 1f);
            SetRuntimeUiField(ui, "devCleanViewEnabled", true);
            ui.RenderRun(run);
            string hiddenDetail = GetRuntimeUiField<string>(ui, "detailedRunHud");
            try
            {
                for (int trap = 0; trap < 3; trap++)
                {
                    if (trap > 0) core.RequestNextPattern(clock += 2f);
                    clock += run.Pattern.CoreSeconds - core.InputTimingOffsetSeconds;
                    core.HandleInput(run.Pattern.Channel, clock);
                    ui.RenderRun(run);
                    Require(run.SuccessCount == trap + 1 && run.Score > 0,
                        "HUD transitions must use real judgement-driven changes, not identical canned text.");
                    if (run.Stopped) break;
                    Require(hud.text.Contains(run.Score.ToString("N0") + "점", StringComparison.Ordinal)
                        && hud.text.Contains("정확 " + run.SuccessCount, StringComparison.Ordinal)
                        && hud.fontSize == 38,
                        "Clean HUD must immediately reflect changed score and judgement totals.");
                    Require(GetRuntimeUiField<string>(ui, "detailedRunHud") == hiddenDetail,
                        "Changing visible totals in clean view must not construct hidden diagnostics.");
                    ui.ToggleDevCleanView();
                    Require(hud.text.Contains("점수 " + run.Score, StringComparison.Ordinal)
                        && hud.text == GetRuntimeUiField<string>(ui, "detailedRunHud"),
                        "F11 must display the latest changed score without another core Tick.");
                    ui.ToggleDevCleanView();
                    hiddenDetail = GetRuntimeUiField<string>(ui, "detailedRunHud");
                    VerifyUnchangedRunHud(ui, run, hud);
                }
                Text result = GetRuntimeUiField<Text>(ui, "detailText");
                Require(run.Stopped && !hud.gameObject.activeSelf && result.text.Contains("정확 3", StringComparison.Ordinal),
                    "Completing practice must replace the HUD with the current result summary.");
                string summary = result.text;
                ui.ToggleDevCleanView();
                ui.ToggleDevCleanView();
                Require(result.text == summary && !hud.gameObject.activeSelf,
                    "Toggling diagnostic visibility on a result must not restore the old live HUD.");
                core.RestartPractice(clock);
                ui.RenderRun(run);
                Require(hud.gameObject.activeSelf && hud.text.StartsWith("0점", StringComparison.Ordinal)
                    && hud.text.Contains("정확 0", StringComparison.Ordinal),
                    "A fresh practice must restore clean HUD totals without the last result's score.");
            }
            finally
            {
                SetRuntimeUiField(ui, "devCleanViewEnabled", false);
                ui.RenderRun(original);
            }
        }

        private static void VerifyUnchangedRunHud(GreedLastRuntimeUi ui, GreedLastRunSnapshot run, Text hud)
        {
            ui.RenderRun(run);
            string text = hud.text;
            int fontSize = hud.fontSize;
            int vertices = 0;
            int layout = 0;
            UnityEngine.Events.UnityAction dirtyVertices = () => vertices++;
            UnityEngine.Events.UnityAction dirtyLayout = () => layout++;
            hud.RegisterDirtyVerticesCallback(dirtyVertices);
            hud.RegisterDirtyLayoutCallback(dirtyLayout);
            try
            {
                for (int frame = 0; frame < 120; frame++) ui.RenderRun(run);
                Debug.Log($"Greed unchanged HUD check: 120 renders, vertex dirties={vertices}, layout dirties={layout}.");
                Require(hud.text == text && hud.fontSize == fontSize && vertices == 0 && layout == 0,
                    "An unchanged live HUD must not alternate detailed/compact text, fonts or layouts inside each RenderRun.");
            }
            finally
            {
                hud.UnregisterDirtyVerticesCallback(dirtyVertices);
                hud.UnregisterDirtyLayoutCallback(dirtyLayout);
            }
        }

        private static void VerifyPlayfieldReadability(GreedLastRuntimeUi ui)
        {
            VerifyCleanRunLaneLabels();
            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            core.Enter();
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.RunCoreTest, "기프트 선택", string.Empty, 0));
            ui.RenderRun(run);
            MethodInfo update = typeof(GreedLastRuntimeUi).GetMethod("Update", BindingFlags.Instance | BindingFlags.NonPublic);
            update.Invoke(ui, null);
            Image[] lanes = GetRuntimeUiField<Image[]>(ui, "laneImages");
            Text[] labels = GetRuntimeUiField<Text[]>(ui, "laneLabelTexts");
            Require(run.ChoiceActive && lanes[0].rectTransform.sizeDelta.x == 440f && labels[0].fontSize == 38,
                "Gameplay choices must use wider, readable selection areas.");
            Require(InvokeRuntimeUiLabel("BuildNormalProgressLabel", run, 3).StartsWith("시작 기프트 선택", StringComparison.Ordinal),
                "Start-gift progress must not be mislabeled as a route choice.");
            Require(!GetRuntimeUiField<GameObject>(ui, "runnerAvatarRoot").activeSelf,
                "The runner must not cover the center gameplay choice.");
            for (int i = 0; i < labels.Length; i++)
                Require(labels[i].rectTransform.anchorMin == Vector2.zero && labels[i].preferredHeight <= labels[i].rectTransform.rect.height,
                    "Choice descriptions must remain inside the expanded choice area.");

            float clock = Time.realtimeSinceStartup;
            core.RestartPractice(clock);
            core.Tick(clock += 2f);
            core.Tick(clock += 1f);
            SetRuntimeUiField(ui, "devCleanViewEnabled", true);
            ui.RenderRun(run);
            update.Invoke(ui, null);
            Require(lanes[0].rectTransform.sizeDelta.x == 195f && labels[0].rectTransform.anchorMin.y > 1f
                && labels[0].text.Split('\n').Length == 2 && !labels[0].text.Contains("충전", StringComparison.Ordinal),
                "Clean gameplay must restore the input area and move concise input labels above the artwork.");
            RectTransform avatar = GetRuntimeUiField<GameObject>(ui, "runnerAvatarRoot").GetComponent<RectTransform>();
            Require(avatar.gameObject.activeSelf && avatar.localScale.y > 1.2f,
                "The live runner must be larger than the old preview while retaining its motion transform.");
            ui.ToggleDevCleanView();
            Require(labels[0].rectTransform.anchorMin == Vector2.zero && labels[0].text.Contains("정확", StringComparison.Ordinal),
                "F11 must immediately restore the developer lane detail.");
            ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteRecordBoard, "기록", "100점", 2));
            Require(labels[0].rectTransform.anchorMin == Vector2.zero,
                "Leaving play must restore stretched labels for menu and slot presentation.");
            core.JumpToDevShortcut(GreedLastDevShortcut.GiftChoice, clock);
            Require(InvokeRuntimeUiLabel("BuildNormalProgressLabel", run, 3).StartsWith("기프트 선택", StringComparison.Ordinal),
                "Gift selection progress must describe the current choice.");
            core.JumpToDevShortcut(GreedLastDevShortcut.RelicChoice, clock);
            Require(InvokeRuntimeUiLabel("BuildNormalProgressLabel", run, 3).StartsWith("유물 선택", StringComparison.Ordinal),
                "Relic selection progress must describe the current choice.");
        }

        private static void VerifyCleanRunLaneLabels()
        {
            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            core.Enter();
            float clock = Time.realtimeSinceStartup;
            string[] directions = { "좌", "중", "우" };
            string[] keys = { "A/←", "S/Space", "D/→" };
            for (int action = 0; action < 5; action++)
            {
                core.JumpToDevShortcut(GreedLastDevShortcut.AvoidanceCycle, clock);
                core.Tick(clock += 2f);
                core.Tick(clock += 1f);
                Require(run.ActivePattern, "Lane-header coverage requires an active pattern.");
                for (int lane = 0; lane < 3; lane++)
                {
                    bool rotationTarget = action >= 3 && (int)run.Pattern.Channel == lane + 1;
                    string desktop = InvokeRuntimeUiLabel("BuildCleanRunLaneLabel", lane, run.Pattern, true, false);
                    string mobile = InvokeRuntimeUiLabel("BuildCleanRunLaneLabel", lane, run.Pattern, false, true);
                    string fallback = InvokeRuntimeUiLabel("BuildCleanRunLaneLabel", lane, run.Pattern, false, false);
                    Require(fallback == directions[lane] + "\n탭",
                        "Touch headers must identify the lane once, without repeating the direction in the tap line.");
                    Require(desktop == directions[lane] + "\n" + (rotationTarget
                            ? (lane == 0 ? "Q/A/←" : "E/D/→") : keys[lane]),
                        "Clean desktop headers must retain actual keyboard inputs, including the active rotation lane.");
                    Require(mobile == (rotationTarget ? directions[lane] + "\n중립→" + directions[lane] + " 기울임" : fallback),
                        "Only the active sensor-supported rotation lane may request neutral-to-tilt input.");
                }
            }
            Require(InvokeRuntimeUiLabel("BuildCleanRunLaneLabel", 0, default(GreedLastPatternModel), false, true) == "좌\n탭"
                && InvokeRuntimeUiLabel("BuildCleanRunLaneLabel", -1, run.Pattern, false, true) == "-",
                "Inactive and invalid header lanes must not retain a previous rotation hint.");
        }

        private static void VerifyCompactTimingGuide(GreedLastRuntimeUi ui)
        {
            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            core.Enter();
            Require(InvokeRuntimeUiLabel("BuildCompactTimingGuideLabel", run) == string.Empty,
                "Choices must not inherit a live timing prompt.");
            MethodInfo publish = typeof(GreedLastRunCore).GetMethod("Publish", BindingFlags.Instance | BindingFlags.NonPublic,
                null, new[] { typeof(float) }, null);
            float clock = Time.realtimeSinceStartup;
            for (int action = 0; action < 5; action++)
            {
                core.JumpToDevShortcut(GreedLastDevShortcut.AvoidanceCycle, clock);
                core.Tick(clock += 2f);
                core.Tick(clock += 1f);
                Require(run.ActivePattern, "Compact timing checks require a live trap.");
                float success = run.Pattern.SuccessWindowSeconds;
                float good = run.Pattern.GoodWindowSeconds;
                float coreTime = clock + run.Pattern.CoreSeconds;
                string window = " · 정확 ±" + Mathf.RoundToInt(success * 1000f) + "ms";
                float[] deltas = { -0.8f, -success * 0.85f, 0f, success * 0.85f, (success + good) * 0.5f, good + 0.02f };
                foreach (float delta in deltas)
                {
                    publish.Invoke(core, new object[] { coreTime + delta });
                    Require(Mathf.Abs(run.CoreDeltaSeconds - delta) < 0.001f, "The guide fixture must use its synthetic publication time.");
                    string label = InvokeRuntimeUiLabel("BuildCompactTimingGuideLabel", run);
                    string expected = delta > good ? "놓침" : delta > success ? "늦음 · Good 가능"
                        : Mathf.Abs(delta) < 0.001f ? "정박" + window
                        : InvokeRuntimeUiLabel("BuildActivePatternBeatCue", run) + window;
                    Require(label == expected && !label.Contains("\n", StringComparison.Ordinal),
                        "Compact timing must reflect the actual beat and success/Good boundaries in one line: " + label);
                    ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.RunCoreTest, "Timing", string.Empty, 0));
                    SetRuntimeUiField(ui, "devCleanViewEnabled", true);
                    ui.RenderRun(run);
                    typeof(GreedLastRuntimeUi).GetMethod("Update", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(ui, null);
                    Text guide = GetRuntimeUiField<Text>(ui, "timingGuideText");
                    Require(guide.text == expected && guide.fontSize == 36 && guide.preferredHeight <= guide.rectTransform.rect.height,
                        "The real clean UI must render the concise timing guide without clipping.");
                }
                core.TogglePause(clock);
                Require(InvokeRuntimeUiLabel("BuildCompactTimingGuideLabel", run) == string.Empty,
                    "Pause must hide live timing prompts instead of telling the player to hit now.");
            }
            ui.ToggleDevCleanView();
        }

        private static void VerifyCompactActionCues(GreedLastRuntimeUi ui)
        {
            var core = new GreedLastRunCore();
            GreedLastRunSnapshot run = default;
            core.SnapshotChanged += value => run = value;
            core.Enter();
            string[] responses = { "점프", "숙이기", "비틀기", "좌회전", "우회전" };
            float clock = Time.realtimeSinceStartup;
            for (int i = 0; i < responses.Length; i++)
            {
                core.JumpToDevShortcut(GreedLastDevShortcut.AvoidanceCycle, clock);
                core.Tick(clock += 2f);
                core.Tick(clock += 1f);
                Require(run.ActivePattern, "Compact action checks require a live avoidance pattern.");
                string cue = InvokeRuntimeUiLabel("BuildCompactActiveActionCueText", run, true, false);
                Require(cue.Split('\n').Length == 2 && cue.Contains(responses[i], StringComparison.Ordinal)
                    && cue.Contains("정확 +" + InvokeRuntimeUiInt("BuildActiveExactScorePreview", run), StringComparison.Ordinal),
                    "Every compact cue must retain its actual action and exact-score preview in two lines.");
                Require(!cue.Contains("보정+", StringComparison.Ordinal) && !cue.Contains("위험 →", StringComparison.Ordinal),
                    "Clean gameplay must not repeat the long timing and comparison paragraph.");
                if (i >= 3)
                {
                    string mobile = InvokeRuntimeUiLabel("BuildCompactActiveActionCueText", run, false, true);
                    string fallback = InvokeRuntimeUiLabel("BuildCompactActiveActionCueText", run, false, false);
                    Require(mobile.Contains("중립→", StringComparison.Ordinal) && mobile.Contains("기울임", StringComparison.Ordinal)
                        && fallback.Contains("탭", StringComparison.Ordinal) && !fallback.Contains("기울임", StringComparison.Ordinal),
                        "Compact rotation cues must preserve neutral-to-tilt guidance and the sensor-unavailable tap fallback.");
                }

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.RunCoreTest, "피라미드 질주", string.Empty, 0));
                SetRuntimeUiField(ui, "devCleanViewEnabled", true);
                ui.RenderRun(run);
                typeof(GreedLastRuntimeUi).GetMethod("Update", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(ui, null);
                Text action = GetRuntimeUiField<Text>(ui, "activeActionCueText");
                Require(action.fontSize == 38 && action.text == InvokeRuntimeUiLabel("BuildCompactActiveActionCueText", run, true,
                    InvokeRuntimeUiStaticBool("IsRuntimeRotationTiltAvailable")),
                    "Clean runtime rendering must select the compact cue without changing the input platform: " + action.text);
                Require(action.preferredHeight <= action.rectTransform.rect.height + 1f,
                    "Both compact action lines must fit without vertical clipping.");
                GreedLastRunSnapshot active = run;
                core.TogglePause(clock + 0.1f);
                Require(string.IsNullOrEmpty(InvokeRuntimeUiLabel("BuildCompactActiveActionCueText", run, true, false)),
                    "Paused gameplay must hide its active cue.");

                // Test the real published outcome separately from the pause visibility assertion.
                core.TogglePause(clock + 0.2f);
                core.Tick(clock += 3f);
                core.HandleInput(active.Pattern.Channel == GreedLastRunChannel.Left
                    ? GreedLastRunChannel.Right : GreedLastRunChannel.Left,
                    clock + active.Pattern.CoreSeconds - core.InputTimingOffsetSeconds);
                Require(run.LastResult == GreedLastJudgementResult.Miss, "Compact failure checks need a real wrong-channel outcome.");
                string feedback = InvokeRuntimeUiLabel("BuildCompactJudgementFeedbackText", run, true, false);
                Require(feedback.Split('\n').Length == 2 && feedback.Contains("Miss", StringComparison.Ordinal)
                    && feedback.Contains("정답", StringComparison.Ordinal) && feedback.Contains("체력 " + run.Health, StringComparison.Ordinal),
                    "Compact failure feedback must retain the correction and actual health without a long paragraph.");
                ui.RenderRun(run);
                Text judgement = GetRuntimeUiField<Text>(ui, "judgementFeedbackText");
                if (!run.ChoiceActive)
                {
                    Require(judgement.fontSize == 36 && judgement.preferredHeight <= judgement.rectTransform.rect.height + 1f,
                        "Compact judgement feedback must fit its two-line area.");
                    RectTransform root = GetRuntimeUiField<RectTransform>(ui, "rootPanelRect");
                    Require(!BoundsInRoot(judgement.rectTransform, root).Overlaps(BoundsInRoot(
                        GetRuntimeUiField<GameObject>(ui, "runGaugeRoot").GetComponent<RectTransform>(), root)),
                        "Compact judgement feedback must not cover health and focus gauges.");
                }
            }
            SetRuntimeUiField(ui, "devCleanViewEnabled", false);
        }

        private static Rect BoundsInRoot(RectTransform child, RectTransform root)
        {
            var corners = new Vector3[4];
            child.GetWorldCorners(corners);
            Vector3 min = root.InverseTransformPoint(corners[0]);
            Vector3 max = root.InverseTransformPoint(corners[2]);
            return Rect.MinMaxRect(min.x, min.y, max.x, max.y);
        }

        internal static void InitializeRuntimeUiSmoke(GreedLastRuntimeUi ui, bool playerControls = false)
        {
            Action action = null;
            Action<int> timingAction = null;
            Action<GreedLastDevShortcut> shortcutAction = null;
            Action<GreedLastRunChannel> channelAction = null;
            ui.Initialize(
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                action,
                timingAction,
                shortcutAction,
                channelAction);
            // Legacy geometry checks exercise detailed tools; app and visual checks use player controls.
            if (playerControls)
                Require(ui.UsePlayerRunControls, "UI initialization must preserve the production player-control default.");
            else if (ui.UsePlayerRunControls)
                ui.ToggleDevCleanView();
        }

        private static void VerifyRuntimeLobbyToRunVisualHandoff()
        {
            GameObject existingCamera = GameObject.Find("GreedLastCamera");
            GameObject existingEventSystem = GameObject.Find("GreedLastEventSystem");
            GameObject host = new GameObject("GreedLastRuntimeUiLaunchSmokeHost");
            GameObject canvasRoot = null;

            try
            {
                GreedLastRuntimeUi ui = host.AddComponent<GreedLastRuntimeUi>();
                InitializeRuntimeUiSmoke(ui);

                GameObject rootPanel = GetRuntimeUiField<GameObject>(ui, "rootPanel");
                if (rootPanel != null)
                {
                    canvasRoot = rootPanel.transform.root.gameObject;
                }

                GameObject runnerAvatarRoot = GetRuntimeUiField<GameObject>(ui, "runnerAvatarRoot");
                Image runnerShadow = GetRuntimeUiField<Image>(ui, "runnerShadow");
                Image[] runnerFootfallPips = GetRuntimeUiField<Image[]>(ui, "runnerFootfallPips");
                Image[] launchGatePieces = GetRuntimeUiField<Image[]>(ui, "straightRunLaunchGatePieces");
                Image launchThresholdSweep = GetRuntimeUiField<Image>(ui, "straightRunLaunchThresholdSweep");
                Image[] runEntryTrapRevealPieces = GetRuntimeUiField<Image[]>(ui, "runEntryTrapRevealPieces");
                Image[] templeEntranceArchPieces = GetRuntimeUiField<Image[]>(ui, "templeEntranceArchPieces");
                Image[] lobbyRunPortalPieces = GetRuntimeUiField<Image[]>(ui, "lobbyRunPortalPieces");
                Image trapMarker = GetRuntimeUiField<Image>(ui, "trapMarker");
                Button rotationTiltButton = GetRuntimeUiField<Button>(ui, "rotationTiltButton");
                Text pauseMenuBodyText = GetRuntimeUiField<Text>(ui, "pauseMenuBodyText");
                CanvasGroup runnerAvatarCanvasGroup = GetRuntimeUiField<CanvasGroup>(ui, "runnerAvatarCanvasGroup");
                Require(
                    runnerAvatarRoot != null
                        && runnerAvatarCanvasGroup != null
                        && runnerShadow != null
                        && runnerFootfallPips != null
                        && runnerFootfallPips.Length == 2
                        && launchGatePieces != null
                        && launchGatePieces.Length == 2
                        && launchThresholdSweep != null
                        && runEntryTrapRevealPieces != null
                        && runEntryTrapRevealPieces.Length == 4
                        && templeEntranceArchPieces != null
                        && templeEntranceArchPieces.Length == 3
                        && lobbyRunPortalPieces != null
                        && lobbyRunPortalPieces.Length == 4
                        && trapMarker != null
                        && rotationTiltButton != null
                        && pauseMenuBodyText != null,
                    "The runtime launch smoke must create the runner, launch staging, and pause sensory controls.");

                var core = new GreedLastRunCore();
                GreedLastRunSnapshot snapshot = default;
                core.SnapshotChanged += value => snapshot = value;
                float now = Time.realtimeSinceStartup + 900f;
                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.LobbyReady, "Lobby", string.Empty, 0));
                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.RunCoreTest, "Practice", string.Empty, 0));
                core.EnterPractice();
                Require(snapshot.StartCountdownActive, "Runtime launch smoke must begin in a real start countdown.");

                ui.RenderRun(snapshot);
                float handoffNow = Time.unscaledTime;
                Require(
                    GetRuntimeUiField<Button[]>(ui, "laneButtons")[0].gameObject.activeSelf
                        && GetRuntimeUiField<Image>(ui, "judgementLine").enabled
                        && !GetRuntimeUiField<Image>(ui, "beatMarker").enabled,
                    "Starting a run from the clean illustrated lobby must restore the lane inputs and timing line without restoring the square behind the runner.");
                SetRuntimeUiField(ui, "runEntranceHandoffStartedAt", handoffNow - 0.17f);
                SetRuntimeUiField(ui, "runEntranceHandoffUntil", handoffNow + 0.17f);
                InvokeRuntimeUiInstance(ui, "UpdateLobbyRunPortal", 0.5f);
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                RectTransform runnerRect = runnerAvatarRoot.GetComponent<RectTransform>();
                float runAvatarScale = (float)typeof(GreedLastRuntimeUi)
                    .GetField("PrototypeRunAvatarScale", BindingFlags.Static | BindingFlags.NonPublic).GetRawConstantValue();
                Require(
                    lobbyRunPortalPieces[3].color.a > 0
                        && runnerAvatarCanvasGroup.alpha < 1f
                        && runnerRect.localScale.x < runAvatarScale
                        && runnerRect.anchoredPosition.y < -10f,
                    "The runtime lobby-to-run handoff must keep a fading threshold behind a runner that is still moving forward from its lobby scale.");
                SetRuntimeUiField(ui, "runEntranceHandoffStartedAt", handoffNow - 0.35f);
                SetRuntimeUiField(ui, "runEntranceHandoffUntil", handoffNow - 0.01f);
                InvokeRuntimeUiInstance(ui, "UpdateLobbyRunPortal", 0.5f);
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                InvokeRuntimeUiInstance(ui, "UpdateStraightRunLaunchGate", true, new Color32(58, 74, 77, 255));
                Require(
                    runnerAvatarRoot.activeSelf
                        && lobbyRunPortalPieces[3].color.a == 0
                        && Mathf.Approximately(runnerAvatarCanvasGroup.alpha, 1f)
                        && runnerRect.anchoredPosition.y < 0f
                        && runnerRect.localScale.x > runAvatarScale
                        && runnerRect.localScale.y < runAvatarScale
                        && launchGatePieces[0].color.a > 0
                        && launchGatePieces[1].color.a > 0,
                    "A real start countdown must crouch the runner behind a visible launch gate.");

                core.Tick(now + 2f);
                core.Tick(now + 3f);
                Require(snapshot.ActivePattern, "Runtime launch smoke must reach its first live trap before testing resume.");
                SetRuntimeUiField(ui, "lastCountdownBeatActive", true);
                SetRuntimeUiField(ui, "lastCountdownWasResume", false);
                ui.RenderRun(snapshot);
                InvokeRuntimeUiInstance(ui, "Update");
                InvokeRuntimeUiInstance(ui, "UpdateTempleDepthBackdrop");
                float revealNow = Time.unscaledTime;
                Require(
                    GetRuntimeUiValueField<float>(ui, "straightRunLaunchReleaseUntil") > revealNow
                        && GetRuntimeUiValueField<float>(ui, "runEntryTrapRevealUntil") > revealNow
                        && !GetRuntimeUiValueField<bool>(ui, "runEntryTrapRevealPending")
                        && templeEntranceArchPieces[2].rectTransform.localScale.x > 1f
                        && templeEntranceArchPieces[0].rectTransform.localScale.y > 1f
                        && templeEntranceArchPieces[0].color.a > 0
                        && templeEntranceArchPieces[1].color.a > 0
                        && templeEntranceArchPieces[2].color.a > 0
                        && launchThresholdSweep.color.a > 0
                        && launchThresholdSweep.rectTransform.anchorMin.y < 0.73f,
                    "The real UI update must release one fresh launch, surge through the existing entrance arch, and consume one first-trap reveal request.");
                SetRuntimeUiField(ui, "runEntryTrapRevealStartedAt", revealNow - 0.31f);
                SetRuntimeUiField(ui, "runEntryTrapRevealUntil", revealNow + 0.31f);
                InvokeRuntimeUiInstance(ui, "UpdateRunTimingVisuals");
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                Require(
                    trapMarker.color.a > 0
                        && runEntryTrapRevealPieces[0].color.a > 0
                        && runEntryTrapRevealPieces[1].color.a > 0
                        && runEntryTrapRevealPieces[2].color.a > 0
                        && runEntryTrapRevealPieces[3].color.a > 0
                        && runEntryTrapRevealPieces[0].rectTransform.anchoredPosition.y > 0f
                        && runEntryTrapRevealPieces[1].rectTransform.anchoredPosition.x > 0f
                        && runEntryTrapRevealPieces[2].rectTransform.anchoredPosition.y < 0f
                        && runEntryTrapRevealPieces[3].rectTransform.anchoredPosition.x < 0f
                        && Mathf.Abs(runnerRect.anchoredPosition.x) <= 7f,
                    "The first real trap after GO must be enclosed by four visible lock-on pieces while the runner keeps only a subtle lane-facing shift.");
                core.TogglePause(now + 3.1f);
                Require(snapshot.Paused && !snapshot.ResumeCountdownActive, "Runtime sensory settings must be exercised from a real paused run.");
                ui.RenderRun(snapshot);
                const string rotationTiltPreferenceKey = "GreedLast.RuntimeUi.RotationTiltEnabled";
                bool rotationTiltPreferenceWasStored = PlayerPrefs.HasKey(rotationTiltPreferenceKey);
                int storedRotationTiltPreference = PlayerPrefs.GetInt(rotationTiltPreferenceKey, 1);
                bool originalTiltPreference = ui.RotationTiltEnabled;
                string toggledTiltLabel = originalTiltPreference ? "기울임 OFF" : "기울임 ON";
                int tiltPreferenceChangedCount = 0;
                bool lastPublishedTiltPreference = originalTiltPreference;
                Action<bool> handleTiltPreferenceChanged = value =>
                {
                    tiltPreferenceChangedCount += 1;
                    lastPublishedTiltPreference = value;
                };
                ui.RotationTiltPreferenceChanged += handleTiltPreferenceChanged;
                try
                {
                    rotationTiltButton.onClick.Invoke();
                    Require(
                        rotationTiltButton.gameObject.activeSelf,
                        "The paused tilt preference button must stay visible while its setting is changed.");
                    Require(
                        ui.RotationTiltEnabled != originalTiltPreference,
                        "The paused tilt preference click must invert its persisted state.");
                    Require(
                        GetButtonLabel(rotationTiltButton) == toggledTiltLabel,
                        "The paused tilt preference button must update immediately. Expected: "
                            + toggledTiltLabel
                            + ", actual: "
                            + GetButtonLabel(rotationTiltButton));
                    Require(
                        pauseMenuBodyText.text.Contains(toggledTiltLabel, StringComparison.Ordinal),
                        "The open pause settings summary must update the tilt preference immediately. Actual: "
                            + pauseMenuBodyText.text);
                    Require(
                        PlayerPrefs.GetInt(rotationTiltPreferenceKey, originalTiltPreference ? 1 : 0)
                                == (originalTiltPreference ? 0 : 1)
                            && tiltPreferenceChangedCount == 1
                            && lastPublishedTiltPreference == !originalTiltPreference,
                        "The tilt preference must persist and notify the input layer exactly once per click.");
                }
                finally
                {
                    if (ui.RotationTiltEnabled != originalTiltPreference)
                    {
                        rotationTiltButton.onClick.Invoke();
                    }

                    ui.RotationTiltPreferenceChanged -= handleTiltPreferenceChanged;
                    if (rotationTiltPreferenceWasStored)
                    {
                        PlayerPrefs.SetInt(rotationTiltPreferenceKey, storedRotationTiltPreference);
                    }
                    else
                    {
                        PlayerPrefs.DeleteKey(rotationTiltPreferenceKey);
                    }

                    PlayerPrefs.Save();
                }
                Require(
                    ui.RotationTiltEnabled == originalTiltPreference
                        && tiltPreferenceChangedCount == 2
                        && lastPublishedTiltPreference == originalTiltPreference
                        && pauseMenuBodyText.text.Contains(
                            originalTiltPreference ? "기울임 ON" : "기울임 OFF",
                            StringComparison.Ordinal),
                    "The runtime tilt smoke must restore the user's original preference after verifying the toggle.");
                core.TogglePause(now + 3.2f);
                Require(snapshot.Paused && snapshot.ResumeCountdownActive, "Runtime launch smoke must enter the real resume countdown.");

                ui.RenderRun(snapshot);
                InvokeRuntimeUiInstance(ui, "Update");
                InvokeRuntimeUiInstance(ui, "UpdateRunTimingVisuals");
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                InvokeRuntimeUiInstance(ui, "UpdateStraightRunLaunchGate", true, new Color32(58, 74, 77, 255));
                InvokeRuntimeUiInstance(ui, "UpdateTempleDepthBackdrop");
                Require(
                    runnerRect.anchoredPosition.y < 0f
                        && runnerRect.localScale.x > runAvatarScale
                        && runnerRect.localScale.y < runAvatarScale
                        && launchGatePieces[0].color.a > 0
                        && launchGatePieces[1].color.a > 0
                        && runEntryTrapRevealPieces[0].color.a == 0
                        && runEntryTrapRevealPieces[1].color.a == 0
                        && runEntryTrapRevealPieces[2].color.a == 0
                        && runEntryTrapRevealPieces[3].color.a == 0
                        && Mathf.Approximately(templeEntranceArchPieces[2].rectTransform.localScale.x, 1f)
                        && Mathf.Approximately(templeEntranceArchPieces[0].rectTransform.localScale.y, 1f)
                        && launchThresholdSweep.color.a == 0,
                    "A real ESC resume countdown must retain the crouched runner and launch gate while clearing the one-time entry cues.");

                core.Tick(now + 5f);
                Require(!snapshot.Paused && !snapshot.CountdownActive, "Runtime launch smoke must release live control after resume GO.");
                ui.RenderRun(snapshot);
                InvokeRuntimeUiInstance(ui, "Update");
                float releaseNow = Time.unscaledTime;
                InvokeRuntimeUiInstance(ui, "UpdateRunnerAvatar");
                InvokeRuntimeUiInstance(ui, "UpdateStraightRunLaunchGate", true, new Color32(58, 74, 77, 255));
                InvokeRuntimeUiInstance(ui, "UpdateTempleDepthBackdrop");
                Require(
                    GetRuntimeUiValueField<float>(ui, "straightRunLaunchReleaseUntil") > releaseNow
                        && GetRuntimeUiValueField<bool>(ui, "straightRunLaunchReleaseWasResume")
                        && !GetRuntimeUiValueField<bool>(ui, "runEntryTrapRevealPending")
                        && runnerRect.anchoredPosition.y > 0f
                        && runnerShadow.gameObject.activeSelf
                        && (runnerFootfallPips[0].color.a > 0 || runnerFootfallPips[1].color.a > 0)
                        && launchGatePieces[0].color.a > 0
                        && launchGatePieces[1].color.a > 0
                        && Mathf.Approximately(templeEntranceArchPieces[2].rectTransform.localScale.x, 1f)
                        && Mathf.Approximately(templeEntranceArchPieces[0].rectTransform.localScale.y, 1f)
                        && launchThresholdSweep.color.a == 0
                        && runEntryTrapRevealPieces[0].color.a == 0
                        && runEntryTrapRevealPieces[1].color.a == 0
                        && runEntryTrapRevealPieces[2].color.a == 0
                        && runEntryTrapRevealPieces[3].color.a == 0,
                    "A real resume GO must keep the launch step and gate while suppressing fresh-run portal and first-trap cues.");

                core.Tick(now + 12f);
                Require(
                    !snapshot.ActivePattern && snapshot.MissCount == 1,
                    "The resumed first trap must be resolvable before the second-pattern regression check.");
                core.RequestNextPattern(now + 14f);
                Require(snapshot.ActivePattern, "Runtime launch smoke must reach a second real trap.");
                ui.RenderRun(snapshot);
                InvokeRuntimeUiInstance(ui, "Update");
                InvokeRuntimeUiInstance(ui, "UpdateRunTimingVisuals");
                InvokeRuntimeUiInstance(ui, "UpdateTempleDepthBackdrop");
                Require(
                    !GetRuntimeUiValueField<bool>(ui, "runEntryTrapRevealPending")
                        && runEntryTrapRevealPieces[0].color.a == 0
                        && runEntryTrapRevealPieces[1].color.a == 0
                        && runEntryTrapRevealPieces[2].color.a == 0
                        && runEntryTrapRevealPieces[3].color.a == 0
                        && Mathf.Approximately(templeEntranceArchPieces[2].rectTransform.localScale.x, 1f)
                        && Mathf.Approximately(templeEntranceArchPieces[0].rectTransform.localScale.y, 1f)
                        && launchThresholdSweep.color.a == 0,
                    "The second real trap must not replay the fresh-run arch pass-through or first-trap lock-on.");
            }
            finally
            {
                if (canvasRoot != null)
                {
                    UnityEngine.Object.DestroyImmediate(canvasRoot);
                }

                DestroySmokeCreatedObject("GreedLastCamera", existingCamera);
                DestroySmokeCreatedObject("GreedLastEventSystem", existingEventSystem);
                GreedLastPrototypeAudioCheck.ReleaseEditorAudio(host);
                UnityEngine.Object.DestroyImmediate(host);
            }
        }

        private static void VerifyRuntimeCleanViewFlow()
        {
            GameObject existingCamera = GameObject.Find("GreedLastCamera");
            GameObject existingEventSystem = GameObject.Find("GreedLastEventSystem");
            GameObject host = new GameObject("GreedLastCleanViewSmokeHost");
            GameObject canvasRoot = null;

            try
            {
                GreedLastRuntimeUi ui = host.AddComponent<GreedLastRuntimeUi>();
                InitializeRuntimeUiSmoke(ui);
                canvasRoot = GetRuntimeUiField<GameObject>(ui, "rootPanel").transform.root.gameObject;
                Button invincibleButton = GetRuntimeUiField<Button>(ui, "devInvincibleButton");
                Button pauseButton = GetRuntimeUiField<Button>(ui, "pauseButton");
                Button[] lanes = GetRuntimeUiField<Button[]>(ui, "laneButtons");
                Button[] volumeButtons = GetRuntimeUiField<Button[]>(ui, "sfxVolumeButtons");
                Button[] timingButtons = GetRuntimeUiField<Button[]>(ui, "timingOffsetButtons");
                CanvasGroup devGroup = invincibleButton.GetComponent<CanvasGroup>();
                CanvasGroup volumeGroup = volumeButtons[0].GetComponent<CanvasGroup>();
                CanvasGroup timingGroup = timingButtons[0].GetComponent<CanvasGroup>();
                var core = new GreedLastRunCore();
                GreedLastRunSnapshot snapshot = default;
                core.SnapshotChanged += value => snapshot = value;
                float now = Time.realtimeSinceStartup;
                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.InfiniteRun, "Infinite", string.Empty, 0));
                core.EnterInfiniteRun();
                core.Tick(now + 3f);
                core.ToggleDevInvincible();
                Require(!snapshot.CountdownActive && snapshot.DevInvincible, "Clean view smoke must start from a live invincible run.");
                ui.RenderRun(snapshot);
                Require(invincibleButton.gameObject.activeSelf && invincibleButton.IsInteractable(), "Development tools must be available before enabling clean view.");

                ui.ToggleDevCleanView();
                ui.RenderRun(snapshot);
                GreedLastRunSnapshot rendered = GetRuntimeUiValueField<GreedLastRunSnapshot>(ui, "latestRunSnapshot");
                Require(
                    devGroup.alpha == 0f && !devGroup.blocksRaycasts && !invincibleButton.IsInteractable()
                        && volumeGroup.alpha == 0f && !volumeGroup.blocksRaycasts
                        && timingGroup.alpha == 0f && !timingGroup.blocksRaycasts
                        && pauseButton.gameObject.activeSelf && pauseButton.IsInteractable()
                        && lanes[0].IsInteractable() && lanes[1].IsInteractable() && lanes[2].IsInteractable()
                        && rendered.DevInvincible && rendered.Score == snapshot.Score
                        && rendered.Distance == snapshot.Distance,
                    "Clean view must hide and disable test/settings surfaces without changing the run or hiding gameplay inputs.");
                Require(!GetRuntimeUiField<Text>(ui, "detailText").enabled,
                    "Active gameplay must not cover the runner and judgement line with introductory paragraphs.");

                core.TogglePause(now + 3.1f);
                ui.RenderRun(snapshot);
                Require(
                    snapshot.Paused && volumeButtons[0].gameObject.activeSelf
                        && volumeGroup.alpha == 1f && volumeGroup.blocksRaycasts && volumeButtons[0].IsInteractable()
                        && timingGroup.alpha == 1f && timingGroup.blocksRaycasts && timingButtons[0].IsInteractable()
                        && devGroup.alpha == 0f && !devGroup.blocksRaycasts && !lanes[0].IsInteractable(),
                    "The pause menu must restore usable sensory settings while clean view keeps development controls hidden.");

                VerifyPauseMenuGeometry(ui, volumeButtons, timingButtons);

                core.TogglePause(now + 3.2f);
                ui.RenderRun(snapshot);
                Require(snapshot.ResumeCountdownActive && !lanes[0].IsInteractable(), "Clean view must not bypass resume countdown input protection.");
                Require(!GetRuntimeUiField<Button>(ui, "nextPatternButton").IsInteractable()
                        && GetRuntimeUiField<Text>(ui, "pauseMenuTitleText").text.StartsWith("재개 ", StringComparison.Ordinal),
                    "Resume countdown must show its count and disable repeated resume clicks.");
                core.Tick(now + 6f);
                ui.RenderRun(snapshot);
                Require(
                    !snapshot.Paused && snapshot.DevInvincible
                        && volumeGroup.alpha == 0f && !volumeGroup.blocksRaycasts
                        && timingGroup.alpha == 0f && !timingGroup.blocksRaycasts
                        && lanes[0].IsInteractable(),
                    "Resuming must hide settings again while preserving invincibility and restoring live lane input.");

                Transform root = GetRuntimeUiField<GameObject>(ui, "rootPanel").transform;
                Require(volumeButtons[0].transform.parent == root && timingButtons[0].transform.parent == root
                        && GetRuntimeUiField<Button>(ui, "nextPatternButton").transform.parent == root
                        && GetRuntimeUiField<Button>(ui, "returnLobbyButton").transform.parent == root,
                    "Leaving pause must return shared controls to the gameplay root, not the hidden menu.");

                ui.Render(BuildUiScreenSnapshot(GreedLastScreenState.LobbyReady, "Lobby", string.Empty, 0));
                Button connectionButton = GetRuntimeUiField<Button>(ui, "debugConnectionButton");
                Require(GetRuntimeUiField<Text>(ui, "detailText").enabled,
                    "Returning to a non-run screen must restore its result and lobby detail text.");
                Require(
                    connectionButton.gameObject.activeSelf && !connectionButton.IsInteractable()
                        && connectionButton.GetComponent<CanvasGroup>().alpha == 0f,
                    "Clean view must survive a run-to-lobby transition without exposing the connection test button.");
                ui.ToggleDevCleanView();
                Require(
                    connectionButton.IsInteractable() && connectionButton.GetComponent<CanvasGroup>().alpha == 1f,
                    "A second clean view toggle must restore the lobby test button without reloading the screen.");
            }
            finally
            {
                if (canvasRoot != null)
                {
                    UnityEngine.Object.DestroyImmediate(canvasRoot);
                }

                DestroySmokeCreatedObject("GreedLastCamera", existingCamera);
                DestroySmokeCreatedObject("GreedLastEventSystem", existingEventSystem);
                GreedLastPrototypeAudioCheck.ReleaseEditorAudio(host);
                UnityEngine.Object.DestroyImmediate(host);
            }
        }

        private static void VerifyPauseMenuGeometry(GreedLastRuntimeUi ui, Button[] volume, Button[] timing)
        {
            RectTransform panel = GetRuntimeUiField<Image>(ui, "pauseMenuPanel").rectTransform;
            Button comfort = GetRuntimeUiField<Button>(ui, "motionComfortButton");
            var controls = new List<Button>(volume);
            controls.AddRange(timing);
            controls.Add(GetRuntimeUiField<Button>(ui, "nextPatternButton"));
            controls.Add(GetRuntimeUiField<Button>(ui, "returnLobbyButton"));
            controls.Add(GetRuntimeUiField<Button>(ui, "rotationTiltButton"));
            controls.Add(GetRuntimeUiField<Button>(ui, "hapticsButton"));
            controls.Add(comfort);
            Canvas.ForceUpdateCanvases();
            var corners = new Vector3[4];
            var bounds = new List<Rect>();
            foreach (Button button in controls)
            {
                Require(button.transform.parent == panel, "Pause controls must belong to the panel: " + button.name);
                if (!button.gameObject.activeInHierarchy) continue;
                button.GetComponent<RectTransform>().GetWorldCorners(corners);
                Vector3 min = panel.InverseTransformPoint(corners[0]);
                Vector3 max = panel.InverseTransformPoint(corners[2]);
                Rect rect = Rect.MinMaxRect(min.x, min.y, max.x, max.y);
                Require(panel.rect.Contains(rect.min) && panel.rect.Contains(rect.max),
                    "Pause control must stay inside the panel at every aspect ratio: " + button.name);
                foreach (Rect previous in bounds)
                    Require(!rect.Overlaps(previous), "Pause controls must not overlap: " + button.name);
                bounds.Add(rect);
            }
            Require(comfort.gameObject.activeInHierarchy && comfort.IsInteractable()
                    && comfort.transform.GetSiblingIndex() > GetRuntimeUiField<Text>(ui, "pauseMenuBodyText").transform.GetSiblingIndex(),
                "Motion comfort must be visible and clickable above the pause backdrop.");
        }

        private static T GetRuntimeUiField<T>(GreedLastRuntimeUi ui, string fieldName) where T : class
        {
            FieldInfo field = typeof(GreedLastRuntimeUi).GetField(
                fieldName,
                BindingFlags.Instance | BindingFlags.NonPublic);
            Require(field != null, "Missing runtime UI field: " + fieldName);
            return field.GetValue(ui) as T;
        }

        private static T GetRuntimeUiValueField<T>(GreedLastRuntimeUi ui, string fieldName) where T : struct
        {
            FieldInfo field = typeof(GreedLastRuntimeUi).GetField(
                fieldName,
                BindingFlags.Instance | BindingFlags.NonPublic);
            Require(field != null, "Missing runtime UI value field: " + fieldName);
            return (T)field.GetValue(ui);
        }

        private static void SetRuntimeUiField<T>(GreedLastRuntimeUi ui, string fieldName, T value)
        {
            FieldInfo field = typeof(GreedLastRuntimeUi).GetField(
                fieldName,
                BindingFlags.Instance | BindingFlags.NonPublic);
            Require(field != null, "Missing runtime UI writable field: " + fieldName);
            field.SetValue(ui, value);
        }

        private static void InvokeRuntimeUiInstance(GreedLastRuntimeUi ui, string methodName, params object[] args)
        {
            MethodInfo method = typeof(GreedLastRuntimeUi).GetMethod(
                methodName,
                BindingFlags.Instance | BindingFlags.NonPublic);
            Require(method != null, "Missing runtime UI instance helper: " + methodName);
            method.Invoke(ui, args);
        }

        private static string GetButtonLabel(Button button)
        {
            Text label = button == null ? null : button.GetComponentInChildren<Text>(true);
            return label == null ? string.Empty : label.text;
        }

        internal static GreedLastStateSnapshot BuildUiScreenSnapshot(
            GreedLastScreenState state,
            string headline,
            string detail,
            int recordBoardPageIndex,
            bool hasUsableSaveSlots = true,
            bool hasOccupiedSaveSlots = true,
            bool saveCandidateAvailable = false,
            string[] saveSlotLabels = null,
            int selectedSaveSlotIndex = 0)
        {
            bool[] saveSlotUsable = hasUsableSaveSlots
                ? new[] { true, true, true }
                : new[] { false, false, false };
            bool[] saveSlotOccupied = hasOccupiedSaveSlots
                ? new[] { true, true, true }
                : new[] { false, false, false };
            string[] labels = saveSlotLabels ?? new[] { "S1", "S2", "S3" };
            return new GreedLastStateSnapshot(
                state,
                0,
                headline,
                detail,
                busy: false,
                coreActionsEnabled: true,
                firstSaveCompleted: true,
                saveLoadoutUnlocked: true,
                infiniteUnlocked: true,
                growthPoints: 0,
                growthSurvivalLevel: 0,
                growthFocusLevel: 0,
                growthTimingLevel: 0,
                recommendedGrowthTrackIndex: -1,
                profileButtonSummary: "Profile",
                selectedSaveSlotIndex: selectedSaveSlotIndex,
                saveSlotLabels: labels,
                saveSlotUsable: saveSlotUsable,
                saveSlotOccupied: saveSlotOccupied,
                saveSlotChoiceRequired: false,
                saveSlotOverwriteConfirmationPending: false,
                saveLoadoutSkipConfirmationPending: false,
                saveSlotDeleteConfirmationPending: false,
                saveSlotDetailViewActive: false,
                saveSlotRenameConfirmationPending: false,
                saveLoadoutCandidateAvailable: saveCandidateAvailable,
                recordBoardPageIndex: recordBoardPageIndex,
                retryVisible: false,
                blockReason: GreedLastConnectBlockReason.None);
        }

        private static bool RuntimePauseBackdropBlocksInput()
        {
            GameObject existingCamera = GameObject.Find("GreedLastCamera");
            GameObject existingEventSystem = GameObject.Find("GreedLastEventSystem");
            GameObject host = new GameObject("GreedLastRuntimeUiSmokeHost");
            GameObject canvasRoot = null;

            try
            {
                GreedLastRuntimeUi ui = host.AddComponent<GreedLastRuntimeUi>();
                Action action = null;
                Action<int> timingAction = null;
                Action<GreedLastDevShortcut> shortcutAction = null;
                Action<GreedLastRunChannel> channelAction = null;
                ui.Initialize(
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    action,
                    timingAction,
                    shortcutAction,
                    channelAction);

                FieldInfo backdropField = typeof(GreedLastRuntimeUi).GetField(
                    "pauseMenuBackdrop",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                Require(backdropField != null, "Missing pause backdrop field.");
                var backdrop = backdropField.GetValue(ui) as Image;

                FieldInfo rootField = typeof(GreedLastRuntimeUi).GetField(
                    "rootPanel",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                Require(rootField != null, "Missing runtime UI root field.");
                var rootPanel = rootField.GetValue(ui) as GameObject;
                if (rootPanel != null)
                {
                    canvasRoot = rootPanel.transform.root.gameObject;
                }

                return backdrop != null && backdrop.raycastTarget;
            }
            finally
            {
                if (canvasRoot != null)
                {
                    UnityEngine.Object.DestroyImmediate(canvasRoot);
                }

                DestroySmokeCreatedObject("GreedLastCamera", existingCamera);
                DestroySmokeCreatedObject("GreedLastEventSystem", existingEventSystem);
                GreedLastPrototypeAudioCheck.ReleaseEditorAudio(host);
                UnityEngine.Object.DestroyImmediate(host);
            }
        }

        private static void DestroySmokeCreatedObject(string name, GameObject existingBeforeSmoke)
        {
            if (existingBeforeSmoke != null)
            {
                return;
            }

            GameObject created = GameObject.Find(name);
            if (created != null)
            {
                UnityEngine.Object.DestroyImmediate(created);
            }
        }

