                        && clearSaveDraftDetail.Contains("다음: 좌 / 중 / 우로 저장할 슬롯 선택", StringComparison.Ordinal)
                        && clearSaveDraftDetail.Contains("선택 전 저장 잠김", StringComparison.Ordinal)
